<?php
if(!defined('UNIOR_INICIADO')){http_response_code(403);exit;}
$id=(int)($_GET['event_id']??0);$cat=(string)($_GET['category_id']??'');$from=trim($_GET['from']??'');$to=trim($_GET['to']??'');
$where=['1=1'];$args=[];
if($id){$where[]='g.event_id=?';$args[]=$id;}
if($cat==='0')$where[]='g.category_id IS NULL';elseif(preg_match('/^\d+$/',$cat)){$where[]='g.category_id=?';$args[]=(int)$cat;}
foreach(['from'=>$from,'to'=>$to] as $key=>$date)if($date!==''){ $d=DateTime::createFromFormat('!Y-m-d',$date);if(!$d||$d->format('Y-m-d')!==$date){http_response_code(400);exit('Fecha inválida.');}$where[]='g.spent_on'.($key==='from'?'>=':'<=').'?';$args[]=$date; }
$condition=implode(' AND ',$where);
$rows=all("SELECT g.category_id,COALESCE(c.name,'Sin categoría') category_name,COUNT(*) n,SUM(g.amount) total FROM expenses g LEFT JOIN expense_categories c ON c.id=g.category_id WHERE ".$condition.' GROUP BY g.category_id,c.name ORDER BY total DESC,category_name',$args);
$total=array_sum(array_column($rows,'total'));$max=$rows?(float)$rows[0]['total']:0;
if(($_GET['export']??'')==='csv'){
 header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="gastos_por_categoria.csv"');$out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,['Categoría','Número de gastos','Total Bs','Porcentaje'],';');
 foreach($rows as $row){$name=$row['category_name'];if(preg_match('/^[\s]*[=+@-]/u',$name))$name="'".$name;fputcsv($out,[$name,$row['n'],$row['total'],$total>0?number_format($row['total']*100/$total,2,'.',''):0],';');}fputcsv($out,['TOTAL',array_sum(array_column($rows,'n')),number_format($total,2,'.',''),($total>0?'100':'0')],';');exit;
}
headerPage('Reporte de otros gastos por categoría');
$categories=all('SELECT id,name FROM expense_categories ORDER BY name');$active=all('SELECT id,name FROM expense_categories WHERE active=1 ORDER BY name');
?>
<div class="card p-4 no-print"><form method="get"><input type="hidden" name="p" value="expense_report"><div class="row"><div class="col-md-4"><?php selectField('event_id','Curso / congreso / taller',[0=>'Todos']+array_column(all('SELECT id,name FROM events ORDER BY starts_at DESC'),'name','id'),(string)$id);?></div><div class="col-md-4"><?php selectField('category_id','Categoría',[''=>'Todas',0=>'Sin categoría']+array_column($categories,'name','id'),$cat);?></div><div class="col-md-2"><?php field('from','Desde',$from,'date',false);?></div><div class="col-md-2"><?php field('to','Hasta',$to,'date',false);?></div></div><button class="btn btn-primary">Generar reporte</button> <button class="btn btn-success" name="export" value="csv">Exportar Excel (CSV)</button> <button class="btn btn-outline-primary" type="button" onclick="print()">Imprimir / PDF</button></form></div>
<div class="card p-4"><h3>UNIOR · Distribución de otros gastos</h3><p><?=e($id?(one('SELECT name FROM events WHERE id=?',[$id])['name']??'Evento no encontrado'):'Todos los eventos')?> · <?=e($from?:'Desde el inicio')?> a <?=e($to?:'la fecha')?> · Generado: <?=e(date('d/m/Y H:i'))?></p><h4>Total gastado: <?=money($total)?></h4><?php if($rows):?><p>Mayor gasto: <b><?=e($rows[0]['category_name'])?> · <?=money($rows[0]['total'])?></b></p><?php endif?><div class="table-responsive"><table class="table table-bordered"><thead><tr><th>Categoría</th><th>N.º de gastos</th><th>Total gastado</th><th>% del total</th><th>Comparación</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><?=e($row['category_name'])?></td><td><?=e($row['n'])?></td><td><?=money($row['total'])?></td><td><?=number_format($total>0?$row['total']*100/$total:0,2)?>%</td><td style="min-width:180px"><div style="background:#eee;height:14px;border-radius:3px"><div style="background:#ba1320;height:100%;width:<?=number_format($max>0?$row['total']*100/$max:0,2,'.','')?>%;border-radius:3px"></div></div></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="5">No hay gastos con los filtros seleccionados.</td></tr><?php endif?></tbody></table></div><p>Ordenado de mayor a menor gasto. Comprende Otros gastos; los costos de materiales se muestran por separado en el reporte financiero.</p></div>
<div class="card p-4"><h3>Detalle y clasificación de gastos</h3><div class="table-responsive"><table class="table"><tr><th>Fecha</th><th>Evento</th><th>Detalle</th><th>Categoría</th><th>Monto</th><th class="no-print">Cambiar categoría</th></tr><?php foreach(all("SELECT g.*,e.name event_name,COALESCE(c.name,'Sin categoría') category_name FROM expenses g JOIN events e ON e.id=g.event_id LEFT JOIN expense_categories c ON c.id=g.category_id WHERE ".$condition.' ORDER BY g.spent_on DESC,g.id DESC LIMIT 500',$args) as $g):?><tr><td><?=e($g['spent_on'])?></td><td><?=e($g['event_name'])?></td><td><?=e($g['description'])?></td><td><?=e($g['category_name'])?></td><td><?=money($g['amount'])?></td><td class="no-print"><form method="post"><?=csrf()?><input type="hidden" name="action" value="classify_expense"><input type="hidden" name="expense_id" value="<?=e($g['id'])?>"><input type="hidden" name="event_id" value="<?=$id?>"><?php selectField('category_id','Categoría',[0=>'Sin categoría']+array_column($active,'name','id'),(string)($g['category_id']??0));?><button class="btn btn-outline-primary btn-sm">Guardar</button></form></td></tr><?php endforeach?></table></div><p>El detalle muestra hasta 500 registros; los totales y la exportación incluyen todos los gastos filtrados.</p></div>
<?php footerPage();
